/** FNV-1a offset basis for 64-bit hash */
const FNV_OFFSET: bigint = 0xcbf29ce484222325n;
/** FNV-1a prime for 64-bit hash */
const FNV_PRIME: bigint = 0x00000100000001B3n;
/** 64-bit mask */
const MASK_64: bigint = 0xFFFFFFFFFFFFFFFFn;

/**
 * Compute FNV-1a 64-bit hash of a string.
 * @param str - The input string.
 * @returns The 64-bit hash value as bigint.
 */
export function fnv1a_64(str: string): bigint {
    let h: bigint = FNV_OFFSET;
    const encoder = new TextEncoder();
    const bytes = encoder.encode(str);
    for (const b of bytes) {
        h = (h ^ BigInt(b)) * FNV_PRIME;
        h = h & MASK_64;
    }
    return h;
}

